from pdfrw import PdfReader

pdf = PdfReader('/root/sc100-blank.pdf')
if pdf.Root.AcroForm:
    print("Form fields found:")
    fields = pdf.Root.AcroForm.Fields
    for field in fields:
        print(f"Field Name: {field.T}")
        if hasattr(field, 'V'):
            print(f"  Value: {field.V}")
        if hasattr(field, 'FT'):
            print(f"  Type: {field.FT}")
        print()
else:
    print("No AcroForm found")
