python3 << 'EOF'
from PyPDF2 import PdfReader

# Read the blank PDF and examine checkbox structure
reader = PdfReader('/root/sc100-blank.pdf')
fields = reader.get_fields()

print("Examining checkbox fields for valid values:")
for field_name in ['Checkbox1[0]', 'Checkbox2[0]', 'Checkbox3[0]']:
    if field_name in fields:
        field = fields[field_name]
        print(f"\n{field_name}:")
        if '/AP' in field:
            print(f"  Appearance: {field['/AP']}")
        if '/V' in field:
            print(f"  Value: {field['/V']}")
        if '/DV' in field:
            print(f"  Default Value: {field['/DV']}")
        if '/AS' in field:
            print(f"  Appearance State: {field['/AS']}")
EOF
